(4, 5, 'Final Year Capstone Project Report - IntelliFile', 'PDF', '2.4 MB', NULL, 'Project Report', 'Internal Storage', 'IMPORTANT', 0, 0, 28, 'Abstract and methodology for IntelliFile AI document search and management application. Implemented system architecture, database schema, and evaluation results. Submission deadline is approaching.', '2026-10-28 05:12:36', '2026-10-28 05:12:36'),
